{
  "candidate_rtl": "module mul_subexpression(
    input [7:0] multiplicand,  // 8-bit multiplicand
    input [7:0] multiplier,    // 8-bit multiplier
    output [15:0] product      // 16-bit product output
);

// Two-dimensional array to hold all partial products
wire [7:0] partial_products[7:0];

genvar i, j;
generate
    for (i = 0; i < 8; i = i + 1) begin: gen_rows
        for (j = 0; j < 8; j = j + 1) begin: gen_cols
            assign partial_products[i][j] = multiplicand[i] & multiplier[j];
        end
    end
endgenerate

// Shifted partial products
wire [15:0] pp_shifted[7:0];
generate
    for (i = 0; i < 8; i = i + 1) begin: gen_shift
        assign pp_shifted[i] = {8'b0, partial_products[i]} << i;
    end
endgenerate

// Balanced binary tree of additions reduces serial adder depth from 7 to 3
wire [15:0] stage1[3:0];
assign stage1[0] = pp_shifted[0] + pp_shifted[1];
assign stage1[1] = pp_shifted[2] + pp_shifted[3];
assign stage1[2] = pp_shifted[4] + pp_shifted[5];
assign stage1[3] = pp_shifted[6] + pp_shifted[7];

wire [15:0] stage2[1:0];
assign stage2[0] = stage1[0] + stage1[1];
assign stage2[1] = stage1[2] + stage1[3];

assign product = stage2[0] + stage2[1];

endmodule",
  "bottleneck": "The original RTL accumulates partial products in a sequential chain of seven 16-bit carry-propagate additions. The measured critical path from multiplicand[3] to product[11] (and similar to product[14]/[15]) shows a long chain of inverting gates corresponding to the carry propagation through this serial adder chain. Source-localization confirms a structural dependency chain of $add operators from sum[3] through sum[7] feeding the high product bits.",
  "rewrite": "Replace the serial accumulation with a balanced binary tree of pairwise additions. The eight shifted partial products are first summed in pairs (stage1), then the four sums are again summed in pairs (stage2), and finally the last two sums are added to form the product. This reduces the number of carry-propagate adder levels in the dependency chain from 7 to 3.",
  "expected_timing_gain": "Estimated 10-20% reduction in maximum data arrival (from 2.78 ns to approximately 2.2-2.5 ns) due to the lower logic depth. The exact gain must be confirmed by STA; synthesis may further restructure the arithmetic.",
  "area_or_other_cost": "Expected area change within +5% to +10% of baseline; the same number of adder bits are used, but the tree topology may incur slightly different wiring or cell sharing. Should remain below the 3261.878400 um^2 cap.",
  "functional_boundaries": "Preserves module name, input/output ports, widths, unsigned full-product behavior for all 2^16 input combinations. No clocks, state, input restrictions, assumptions, or don't-cares are introduced."
}
